algorithms.pseudocode:
function MINIMAL-SOUND-FILTER(m, label, bound):
    F <- empty map from label to set of residues
    for each prime p with 5 <= p < bound and gcd(p, m) = 1:
        F[label(p)] <- F[label(p)] union { p mod m }
    return F                       // every sound filter contains F pointwise

function NARROWING-FACTOR(m, (t1, t2), label, bound):
    F <- MINIMAL-SOUND-FILTER(m, label, bound)
    A <- F[t1];  B <- F[t2]
    if A union B is empty: return 1
    return |A intersect B| / |A union B|
    // value 1  => no sound filter can exclude any class (no pinning)
    // value 0  => the two labels partition the classes (a real filter)
